You are a formal verification assistant. The following Dafny program fails Dafny verification.

=== PROGRAM ===
//https://homepage.cs.uiowa.edu/~tinelli/classes/181/Fall21/Tools/Dafny/Examples/selection-sort.shtml

predicate sorted (a: array<int>)
	requires a != null
	reads a
{
	sorted'(a, a.Length)
}

predicate sorted' (a: array<int>, i: int)
	requires a != null
	requires 0 <= i <= (a.Length) + 1
	reads a
{
	forall k :: 0 < k < i ==> a[k-1] <= a[k]
}


// Selection sort on arrays

method SelectionSort(a: array<int>) 
  modifies a
  ensures sorted(a)
  //ensures multiset(old(a[..])) == multiset(a[..])
{
  var n := 0;
  while (n != a.Length)
    invariant 0 <= n <= a.Length
    invariant forall i, j :: 0 <= i < n <= j < a.Length ==> a[i] <= a[j] //all the values in the sorted section will be lower then any value in the non sorted section 
    invariant forall k1, k2 :: 0 <= k1 < k2 < n ==> a[k1] <= a[k2] //all values in the sorted section are sorted with respect to one another
  {
    var mindex := n;
    var m := n + 1;
    while (m != a.Length)
      invariant n <= m <= a.Length //m (search idx) between valid range
      invariant n <= mindex < m <= a.Length // minIndex between valid range
      invariant forall i :: n <= i < m ==> a[mindex] <= a[i]  //mindex is current smallest in range n < m
    {
      if (a[m] < a[mindex]) {
        mindex := m;
      }
      m := m + 1;
    }
    a[n], a[mindex] := a[mindex], a[n];
    n := n + 1;
  }
}

=== DAFNY ERROR ===
program.dfy(15,38): Error: index out of range

Dafny program verifier finished with 3 verified, 1 error

=== COUNTEREXAMPLE ===
At initial state: a.Length = 7720, i = 7721.

Analyze the failure and respond with ONLY a valid JSON object — no explanation, no markdown, no code fences. Use exactly this structure:

{
  "spec_element": "<one of: requires | invariant | ensures>",
  "proof_obligation": "<one of: initiation | preservation | bridge>",
  "diagnosis": "<explanation of what broke and why>",
  "repair": "<the corrected Dafny specification line that restores the intended behavior>"
}

Definitions:
- requires: the precondition that must hold before the method executes
- invariant: the loop invariant that must hold throughout the loop
- ensures: the postcondition that the method must guarantee on return
- initiation: the precondition does not establish the invariant at loop entry
- preservation: the loop body does not maintain the invariant
- bridge: the invariant and loop exit condition do not imply the postcondition

